// 简化状态机：条件集中判定，转移只做一件事
enum State { Idle, Run, Jump, Land }

State Evaluate(State current, InputState input, float speed, bool grounded) {
    switch (current) {
        case State.Idle:
            // 速度超过阈值才进入跑步，避免边界抖动
            if (speed > 0.1f) return State.Run;
            if (!grounded && input.JumpPressed) return State.Jump;
            return State.Idle;
        case State.Run:
            if (speed <= 0.05f) return State.Idle;
            return State.Run;
        case State.Jump:
            // 只有落地且垂直速度已归零才切回，防止连跳时状态反复
            if (grounded && speed < 0.1f) return State.Land;
            return State.Jump;
        case State.Land:
            return speed > 0.1f ? State.Run : State.Idle;
        default:
            return State.Idle;
    }
}

// 过渡时间按动作类型区分，跳跃用更短的过渡保持响应
float TransitionTime(State from, State to) =>
    (to == State.Jump || from == State.Jump) ? 0.08f : 0.2f;

// 资源更新：比对清单、差量下载、校验后原子切换
async Task<bool> UpdateAssets(Manifest remote, Manifest local) {
    var plan = remote.Diff(local);                 // 只下载哈希不同的文件
    long total = plan.Sum(f => f.Size);
    Debug.Log($"need {plan.Count} files, {total / 1024 / 1024} MB");

    foreach (var file in plan) {
        var data = await Download(file.Url, resumeFrom: LocalSize(file));  // 支持断点续传
        if (Hash(data) != file.Hash) {
            Rollback("hash mismatch: " + file.Path);   // 校验失败立即回滚
            return false;
        }
        WriteToStaging(file.Path, data);              // 先写临时目录
    }

    CommitStaging();   // 全部校验通过后一次性切换，避免半更新状态
    return true;
}

